<template>
  <div class="propose-page">
    <ZsSteps class="decision-step" :active="active" :list="['选择房屋', '选择倡议项', '签字']"></ZsSteps>
    <div class="page-body">
      <StepChoose v-show="active == 0" @next="getStep1" />
      <StepPropose v-show="active == 1" :complexId="complexId" @next="active++" @prev="active--" />
      <StepSign v-show="active == 2" @prev="active--" @next="submit" />
    </div>

    <ZsPopup v-model:show="showPopup" title="倡议成功" type="success">
      <p>您的倡议已成功提交审核，请耐心等待审核结果！</p>
      <template #footer>
        <ZsButton type="primary" @click="confirm">确认</ZsButton>
      </template>
    </ZsPopup>
  </div>
</template>

<script setup>
import { onUnmounted, ref } from 'vue'
import StepChoose from '@/pages_owner/propose/components/StepChoose.vue'
import StepPropose from '@/pages_owner/propose/components/StepPropose.vue'
import StepSign from '@/pages_owner/decision/components/StepSign.vue'
import { batchSaveSuggestTopic } from '@/api/autonomy'
import userStore from '@/store/user'
import voteStore from '@/store/vote'
import { onLoad } from '@dcloudio/uni-app'

const recordPropertyId = ref('')
onLoad((options) => {
  recordPropertyId.value = options.complexId
})
const active = ref(0)
const showPopup = ref(false)
const complexId = ref('')
const houseId = ref('')

if (recordPropertyId) {
  complexId.value = recordPropertyId
  active.value = 1
}

const confirm = () => {
  showPopup.value = false
  uni.redirectTo({
    url: 'index',
  })
}

const getStep1 = (data) => {
  active.value++
  complexId.value = data.complexId
  houseId.value = data.houseId
}

const submit = () => {
  const list = voteStore.proposeSelections.map((el) => ({
    ...el,
    initiatorIdNumber: userStore.idNumber,
    complexId: complexId.value,
    houseId: houseId.value,
    signatureUrl: voteStore.signUrl,
  }))
  batchSaveSuggestTopic(list).then(() => {
    showPopup.value = true
    voteStore.clear()
    uni.navigateBack({ delta: 1 })
  })
}
</script>

<style lang="scss" scoped>
.propose-page {
  background-color: $uni-bg-color-grey;
  padding: 12px 10px;
}

.page-body {
  margin-top: 12px;
}
</style>
